/** A gradient fill for a one-path mark (Instagram), in the mark's own box (0..1). */
export type BrandGradient = {
  readonly type: "radial" | "linear";
  readonly stops: readonly (readonly [offset: number, hex: string])[];
  /** radial: centre and radius; linear: the line from (x1,y1) to (x2,y2). */
  readonly cx?: number;
  readonly cy?: number;
  readonly r?: number;
  readonly x1?: number;
  readonly y1?: number;
  readonly x2?: number;
  readonly y2?: number;
};

/**
 * One brand mark in its real colours. Either one path in one colour (with an
 * optional gradient, e.g. Instagram), or several paths each in its own colour
 * (e.g. Google Calendar, Razorpay). `viewBox` defaults to the 24px grid.
 */
export type BrandMark = { readonly title: string; readonly viewBox?: string } & (
  | { readonly path: string; readonly hex: string; readonly gradient?: BrandGradient }
  | { readonly paths: readonly { readonly d: string; readonly hex: string }[] }
);

